const items = $input.all();

// ponytail: keyword tiers, tune weights/terms here
const TIERS = [
  { weight: 3, terms: [
    'visa', 'visum', 'aufenthalt', 'asyl', 'migration', 'migrant',
    'einbürgerung', 'citizenship', 'integration', 'ausländer', 'foreigner',
    'immigration', 'residence permit', 'work permit', 'arbeitserlaubnis',
    'abschiebung', 'deportation'
  ]},
  { weight: 2, terms: [
    'wohnung', 'miete', 'housing', 'rent', 'arbeitsmarkt', 'labor market',
    'fachkräfte', 'gesetz', 'law', 'bundestag', 'bundesrat', 'kranken',
    'health insurance', 'bürgergeld', 'mindestlohn', 'minimum wage',
    'diskriminierung', 'racism', 'rassismus'
  ]},
  { weight: 1, terms: [
    'regierung', 'government', 'koalition', 'steuer', 'tax',
    'bahn', 'streik', 'strike', 'unwetter', 'storm', 'flut'
  ]}
];

const score = (title, snippet) => {
  const t = title.toLowerCase();
  const s = snippet.toLowerCase();
  let total = 0;
  for (const { weight, terms } of TIERS) {
    for (const term of terms) {
      if (t.includes(term)) total += weight * 2;   // title hit counts double
      else if (s.includes(term)) total += weight;
    }
  }
  return total;
};

const cutoff = Date.now() - 48 * 60 * 60 * 1000;

const scored = items
  .map(i => {
    const title = i.json.title || '';
    const snippet = (i.json.contentSnippet || i.json.summary || i.json.content || '')
      .replace(/<[^>]+>/g, '').substring(0, 300);
    const date = i.json.isoDate || i.json.pubDate || '';
    return { title, snippet, link: i.json.link || '', date, ts: new Date(date || 0).getTime(), score: score(title, snippet) };
  })
  .filter(a => a.ts >= cutoff)                     // drop stale RSS backlog
  .sort((a, b) => b.score - a.score || b.ts - a.ts); // score desc, then newest

const articles = scored.slice(0, 40).map(({ title, link, date, snippet }) => ({ title, link, date, snippet }));

return [{ json: { articles } }];

const text = $input.first().json.output || '';

// Split on --- separator between articles
const blocks = text.split(/\n---\n/).map(b => b.trim()).filter(Boolean);

const cards = blocks.map(block => {
  const lines = block.split('\n').filter(Boolean);
  const titleLine = lines[0] || '';
  const titleMatch = titleLine.match(/^\d+\.\s+(.+)$/);
  const title = titleMatch ? titleMatch[1].trim() : titleLine;

  const get = label => {
    const line = lines.find(l => l.toLowerCase().startsWith(label.toLowerCase()));
    return line ? line.replace(/^[^:]+:\s*/i, '').trim() : '';
  };

  const sourceDate = get('Source & Date:');
  const link       = get('Link:');
  const summary    = get('Summary:');
  const why        = get('Why it matters:');
  const readMore   = link ? `<a href="${link}" style="display:inline-block;margin-top:12px;font-size:12px;color:#1a73e8;text-decoration:none;font-weight:600;">Read article &rarr;</a>` : '';

  return `<div style="margin-bottom:24px;padding:20px;background:#fff;border-radius:8px;border-left:4px solid #1a73e8;box-shadow:0 1px 3px rgba(0,0,0,.1);">
    <h3 style="margin:0 0 6px 0;font-size:16px;color:#1a1a1a;line-height:1.4;">${title}</h3>
    <p style="margin:0 0 10px 0;font-size:11px;color:#888;">${sourceDate}</p>
    <p style="margin:0 0 12px 0;font-size:14px;color:#333;line-height:1.6;">${summary}</p>
    <div style="background:#f0f4ff;padding:10px 14px;border-radius:4px;">
      <span style="font-size:12px;font-weight:700;color:#1a73e8;">WHY IT MATTERS: </span>
      <span style="font-size:12px;color:#444;">${why}</span>
    </div>
    ${readMore}
  </div>`;
}).join('');

const today = DateTime.now().toFormat('MMMM d, yyyy');

const html = `<!DOCTYPE html><html><head><meta charset="UTF-8"></head>
<body style="margin:0;padding:0;background:#f5f5f5;font-family:-apple-system,BlinkMacSystemFont,'Segoe UI',Roboto,sans-serif;">
<div style="max-width:620px;margin:0 auto;padding:24px 16px;">
  <div style="background:#1a73e8;padding:24px;border-radius:8px 8px 0 0;text-align:center;">
    <h1 style="margin:0;color:#fff;font-size:22px;font-weight:600;">Germany Daily Update</h1>
    <p style="margin:6px 0 0 0;color:#c8dcff;font-size:13px;">${today} &middot; Top 5 for migrants in Germany</p>
  </div>
  <div style="background:#e8f0fe;padding:14px 24px;margin-bottom:20px;">
    <p style="margin:0;font-size:13px;color:#444;">Filtered from tagesschau, DW, and Zeit Online &mdash; curated for integration, visa, and daily life.</p>
  </div>
  ${cards}
  <p style="text-align:center;font-size:11px;color:#aaa;margin-top:24px;">Automated by n8n &middot; tagesschau &middot; DW &middot; Zeit Online</p>
</div></body></html>`;

return [{ json: { html } }];
